# 用你的代码替换 __

class Stack:
    def __init__(self):
        self.stack = []

    def push(self, item):
        self.stack.append(item)

    def pop(self):
        self.stack.pop()

    def is_empty(self):
        return len(self.stack) == 0

stack1 = Stack()

# 将项目添加到栈中
text = input()

for character in text:
    stack1.push(character)

result = ''

while True:
    if stack1.is_empty():
        break

    # 从栈中弹出元素并添加到结果字符串中
    result += stack1.stack.pop()

print(result)
